INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46211, 'Numbers 21:15', 'Numbers', 21, 15, 'د هغه درې د موآبیانو د سرحد تر څنګ پرتې دي او د عار تر ښاره پورې رسېدلې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_15.mp3', '', 1761754199, 1761754199),
(46212, 'Numbers 21:16', 'Numbers', 21, 16, 'د هغه ځای څخه دوی یو بل ځای ته چې د څاه په نوم یادېده لاړل، یعنې هغه ځای ته چې څښتن موسی ته وویل: «خلک سره راټول کړه چې د څښلو دپاره اوبه ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_16.mp3', '', 1761754199, 1761754199),
(46213, 'Numbers 21:17', 'Numbers', 21, 17, 'په هغه وخت کې د اسراییلو خلکو دا روحاني سندره وویله: ای څاه! راوباسه اوبه خپلې هرکلی به ورته وایو په سندرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_17.mp3', '', 1761754199, 1761754199),
(46214, 'Numbers 21:18', 'Numbers', 21, 18, 'هغه څاه چې کیندل شوې شاهزاد ګانو له خوا او د قوم د مشرانو له خوا ده کیندل شوې په شاهي امسا او د هغوی په امساګانو باندې هغوی له دښتې څخه متانې ته لاړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_18.mp3', '', 1761754199, 1761754199),
(46215, 'Numbers 21:19', 'Numbers', 21, 19, 'او د هغه ځای نه نحلي ییل ته لاړل او د نحلي ییل څخه باموت ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_19.mp3', '', 1761754199, 1761754199),
(46216, 'Numbers 21:20', 'Numbers', 21, 20, 'او د باموت څخه هغې درې ته لاړل چې د موآبیانو په سیمه کې ده او د پیسګاه د غره لاندې ده او د هغه ځای څخه ښکته دښته لیدل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_20.mp3', '', 1761754199, 1761754199),
(46217, 'Numbers 21:21', 'Numbers', 21, 21, 'د اسراییلو خلکو د اموریانو پاچا سیحون ته استازي ورولېږل چې هغه ته داسې ووایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_21.mp3', '', 1761754199, 1761754199),
(46218, 'Numbers 21:22', 'Numbers', 21, 22, '«مهرباني وکړئ مونږ پرېږدئ چې ستاسو په هېواد باندې تېر شو. مونږ به خپله لاره نه پرېږدو او ستاسو پټیو او د انګورو باغونو ته به نه ورننوځو او ستاسو د څاه ګانو څخه به هېڅ اوبه ونه څښو. مونږ به په لویه لاره باندې ځو، ترڅو ستاسو د پولې څخه ووځو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_22.mp3', '', 1761754199, 1761754199),
(46219, 'Numbers 21:23', 'Numbers', 21, 23, 'خو سیحون اسراییلیان پرېنښودل چې د هغه د وطن له لارې سفر وکړي. د دې په ځای، هغه خپل ټول لښکر سره راټول کړ او دښتې ته ووت چې د یاهص ښار ته نژدې په اسراییلیانو باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_23.mp3', '', 1761754199, 1761754199),
(46220, 'Numbers 21:24', 'Numbers', 21, 24, 'خو اسراییلیانو خپل ډېر دښمنان په دې جګړه کې ووژل او د هغوی سیمه یې په جنوب کې د ارنون د سیند څخه نیولې په شمال کې د یبوق تر سیند پورې ونیوله. د یبوق بلې خواته د عمونیانو سیمه وه او د هغوی سرحد ډېر قوي ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_24.mp3', '', 1761754199, 1761754199),
(46221, 'Numbers 21:25', 'Numbers', 21, 25, 'نو اسراییلیانو د اموریانو ټول ښارونه چې په هغو کې حشبون او د هغه شاوخوا کلي هم شامل وو، ونیول او هلته اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_25.mp3', '', 1761754199, 1761754199),
(46222, 'Numbers 21:26', 'Numbers', 21, 26, 'حشبون د اموریانو د پاچا سیحون پایتخت ؤ. سیحون د موآب د پخواني پاچا سره جګړه کړې وه او د ارنون د سیند پورې یې د هغه ټوله خاوره نیولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_26.mp3', '', 1761754199, 1761754199),
(46223, 'Numbers 21:27', 'Numbers', 21, 27, 'په دې سبب شاعران وایي: راشئ حشبون ته یعنې ښار ته د سیحون پاچا غواړو هغه بېرته اباد ووینو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_27.mp3', '', 1761754199, 1761754199),
(46224, 'Numbers 21:28', 'Numbers', 21, 28, 'په یو وخت کې د حشبون له دغه ښاره مخکې لاړې د سیحون لښکرې لکه د اور په شان په موآب کې یې برباد کړ د عار ښار کړې بربادې یې غونډۍ ارنون دپاسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_28.mp3', '', 1761754199, 1761754199),
(46225, 'Numbers 21:29', 'Numbers', 21, 29, 'افسوس په تاسو موآبیانو باندې! ای د کموش عبادت کوونکو برباد شوئ تاسې ستاسو خدای پرېښودل خلک چې شي مهاجر ښځې شولې اسیرانې د اموریایي پاچا په لاس', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_29.mp3', '', 1761754199, 1761754199),
(46226, 'Numbers 21:30', 'Numbers', 21, 30, 'خو اوس ده برباد شوې اولاده د هغوی په ټوله لاره د حشبون نه تر دیبونه پورې تر نوفح چې ده میدیبا ته نژدې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_30.mp3', '', 1761754199, 1761754199),
(46227, 'Numbers 21:31', 'Numbers', 21, 31, 'نو اسراییلیان د اموریانو په سیمه کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_31.mp3', '', 1761754199, 1761754199),
(46228, 'Numbers 21:32', 'Numbers', 21, 32, 'نو موسی یو څو کسان ولېږل چې د یعزیر په ښار باندې د حملې دپاره یوه ښه لاره راپیدا کړي. اسراییلیانو هغه ښار او د هغه شاوخوا کلي ونیول او هغه اموریان چې هلته اوسېدل، هغوی یې وشړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_32.mp3', '', 1761754199, 1761754199),
(46229, 'Numbers 21:33', 'Numbers', 21, 33, 'بیا اسراییلیان راوګرځېدل او د باشان په لاره باندې روان شول. د باشان پاچا عوج د خپلو ټولو لښکرو سره روان شو چې په ادرعي کې په هغوی باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_33.mp3', '', 1761754199, 1761754199),
(46230, 'Numbers 21:34', 'Numbers', 21, 34, 'څښتن موسی ته وویل: «د عوج څخه مه وېرېږه. زه به تاته په هغه، د هغه په ټولو خلکو او خاوره باندې بری درکړم. د هغه سره هغه کار وکړه چې د اموریانو د پاچا سره دې چې حشبون یې پایتخت ؤ، کړی ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_34.mp3', '', 1761754199, 1761754199),
(46231, 'Numbers 21:35', 'Numbers', 21, 35, 'نو اسراییلیانو عوج، د هغه زامن او د هغه ټول خلک ووژل، یو هم ژوندی پاتې نه شو او بیا یې د هغه خاوره ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_35.mp3', '', 1761754199, 1761754199),
(46232, 'Exodus 34:1', 'Exodus', 34, 1, 'څښتن موسی ته وویل: «د لومړنیو لوحو په شان د تیږو دوه لوحې تیارې کړه، زه به په هغو باندې هغه خبرې ولیکم چې په لومړنیو لوحو باندې لیکل شوې وې او تا ماتې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_1.mp3', '', 1761754199, 1761754199),
(46233, 'Exodus 34:2', 'Exodus', 34, 2, 'سبا سهار تیار اوسه او د سینا غره ته راوخېژه او د غره په سر باندې ماته ځان حاضر کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_2.mp3', '', 1761754199, 1761754199),
(46234, 'Exodus 34:3', 'Exodus', 34, 3, 'ستا سره دې هېڅوک نه راځي او په غره باندې دې په هېڅ ځای کې څوک ونه لیدل شي، حتی رمې او پادې دې هم د غره په لمنه کې نه څري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_3.mp3', '', 1761754199, 1761754199),
(46235, 'Exodus 34:4', 'Exodus', 34, 4, 'نو موسی د څښتن د حکم سره سم د لومړنیو لوحو په شان دوه د تیږو لوحې تیارې کړې. هغه سهار وختي پاڅېده او لوحې یې د ځان سره واخیستلې او د سینا غره ته پورته شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_4.mp3', '', 1761754199, 1761754199),
(46236, 'Exodus 34:5', 'Exodus', 34, 5, 'بیا څښتن په ورېځ کې راښکته شو او د موسی سره هلته ودرېده او خپل سپېڅلی نوم یې «څښتن» اعلان کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_5.mp3', '', 1761754199, 1761754199),
(46237, 'Exodus 34:6', 'Exodus', 34, 6, 'بیا څښتن د موسی په مخکې تېر شو او دا غږ یې وکړ: «زه څښتن یعنې څښتن خدای یم، زه رحیم او مهربانه خدای یم. زر نه په قهرېږم او تلپاتې مینه او وفاداري کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_6.mp3', '', 1761754199, 1761754199),
(46238, 'Exodus 34:7', 'Exodus', 34, 7, 'د زرګونو خلکو سره تلپاتې مینه کوم او زه بدي، سرغړونه او ګناه بخښم. خو ګناهکاران هیڅکله بې سزا نه پرېږدم او د پلرونو د ګناه سزا به د هغوی اولادونو او لمسیو ته تر درېم او څلورم نسله پورې ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_7.mp3', '', 1761754199, 1761754199),
(46239, 'Exodus 34:8', 'Exodus', 34, 8, 'موسی سمدلاسه په سجده شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_8.mp3', '', 1761754199, 1761754199),
(46240, 'Exodus 34:9', 'Exodus', 34, 9, 'هغه وویل: «ای څښتنه، که چېرې ته په رښتیا سره زما څخه خوشحاله یې، نو ستا څخه غوښتنه کوم چې زمونږ سره لاړ شه. که څه هم دا قوم سرزوری دی، خو ته زمونږ بدي او ګناه وبخښه او مونږ د خپل قوم په توګه قبول کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_9.mp3', '', 1761754199, 1761754199),
(46241, 'Exodus 34:10', 'Exodus', 34, 10, 'بیا څښتن موسی ته وویل: «زه اوس د اسراییلو د خلکو سره یو لوظ کوم. زه به د هغوی په مخکې داسې عجیبه کارونه وکړم چې د ټولې نړۍ په هېڅ یو قوم کې شوي نه وي. کوم خلک چې تاسو یې په منځ کې اوسېږئ، هغوی به وویني چې زه څښتن ستاسو دپاره څومره هیبتناکه کارونه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_10.mp3', '', 1761754199, 1761754199),
(46242, 'Exodus 34:11', 'Exodus', 34, 11, 'نن چې زه تاسو ته کوم حکمونه درکوم هغو ته غاړه کېږدئ. نو بیا به زه اموریان، کنعانیان، حیتیان، فرزیان، حویان او یبوسیان ستاسو له مخې څخه لېرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_11.mp3', '', 1761754199, 1761754199),
(46243, 'Exodus 34:12', 'Exodus', 34, 12, 'کوم وطن ته چې تاسو روان یئ، پام کوئ چې د هغه وطن له اوسېدونکو سره کوم تړون ونه کړئ. که نه، نو د هغوی په دام کې به راګېر شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_12.mp3', '', 1761754199, 1761754199),
(46244, 'Exodus 34:13', 'Exodus', 34, 13, 'د هغوی د قربانۍ ځایونه وران کړئ، هغه لویې تیږې چې د عبادت دپاره ورڅخه کار اخیستل کیږي، ماتې کړئ او د اشیره بتان یې راوغورځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_13.mp3', '', 1761754199, 1761754199),
(46245, 'Exodus 34:14', 'Exodus', 34, 14, 'د بل خدای عبادت مه کوئ، ځکه څښتن چې نوم یې غیرتي دی، هغه غیرتي خدای دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_14.mp3', '', 1761754199, 1761754199),
(46246, 'Exodus 34:15', 'Exodus', 34, 15, 'پام کوئ چې د هغه وطن د اوسېدونکو سره کوم تړون ونه کړئ، ځکه کله چې هغوی د خپلو خدایانو عبادت کوي او قرباني ورته وړاندې کوي، نو تاسو ته به هم بلنه درکړي او تاسو به بې لارې کړي، ترڅو د هغوی قربانۍ وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_15.mp3', '', 1761754199, 1761754199),
(46247, 'Exodus 34:16', 'Exodus', 34, 16, 'که چېرې تاسو د هغوی لورګانې خپلو زامنو ته په نکاح کړئ، نو څرنګه چې هغوی د خپلو خدایانو عبادت کوي، نو ستاسو زامن به هم خپلې لارې ته راواړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_16.mp3', '', 1761754199, 1761754199),
(46248, 'Exodus 34:17', 'Exodus', 34, 17, 'خپلو ځانونو ته د فلز څخه بتان مه جوړوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_17.mp3', '', 1761754199, 1761754199),
(46249, 'Exodus 34:18', 'Exodus', 34, 18, 'د فطیرې ډوډۍ اختر ولمانځئ. لکه څنګه چې ما تاسو ته حکم کړی دی، اووه ورځې فطیره ډوډۍ وخورئ. دا کار د ابیب په میاشت کې په ټاکل شوي وخت وکړئ، ځکه چې په دې میاشت کې تاسو له مصر څخه راووتلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_18.mp3', '', 1761754199, 1761754199),
(46250, 'Exodus 34:19', 'Exodus', 34, 19, 'ستاسو په کورنیو کې هر لومړني زېږول شوي نران او ستاسو د رمو او پادو لومړني زېږول شوي نران بچي زما دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_19.mp3', '', 1761754199, 1761754199),
(46251, 'Exodus 34:20', 'Exodus', 34, 20, 'لومړنی زېږېدل شوی خر د یو وري سره بدل کړئ، خو که چېرې تاسو هغه بدل نه کړ، نو د هغه خر ورمېږ مات کړئ. خپل ټول لومړني زېږول شوي زامن بېرته په بیه واخلئ. هېڅوک دې ماته تش لاس رانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_20.mp3', '', 1761754199, 1761754199),
(46252, 'Exodus 34:21', 'Exodus', 34, 21, 'شپږ ورځې کار وکړئ. خو په اوومه ورځ ارام وکړئ، حتی د قلبې او لو په وخت کې هم باید کار ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_21.mp3', '', 1761754199, 1761754199),
(46253, 'Exodus 34:22', 'Exodus', 34, 22, 'کله چې تاسو د غنمو د لومړني حاصل لو کول پیل کوئ، نو د لو کولو اختر ولمانځئ او د لومړني حاصل د راټولولو اختر په مني کې ولمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_22.mp3', '', 1761754199, 1761754199),
(46254, 'Exodus 34:23', 'Exodus', 34, 23, 'ستاسو ټول نارینه باید په کال کې درې ځلې څښتن تعالی یعنې د اسراییلو خدای ته د عبادت دپاره راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_23.mp3', '', 1761754199, 1761754199),
(46255, 'Exodus 34:24', 'Exodus', 34, 24, 'کله چې تاسو په هر کال کې درې ځلې د خپل څښتن خدای حضور ته د عبادت دپاره راځئ، نو هېڅوک به په تاسو باندې حمله نه کوي او ستاسو جایداد به نه نیسي. زه به هغه قومونه چې ستاسو په وړاندې ودریږي، لېرې کړم او ستاسو سیمه به پراخه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_24.mp3', '', 1761754199, 1761754199),
(46256, 'Exodus 34:25', 'Exodus', 34, 25, 'کله چې تاسو ماته یو حیوان قرباني کوئ، نو هغه د خمیرې ډوډۍ سره مه وړاندې کوئ. کوم حیوان چې د فسحې په اختر کې حلالیږي، د هغه د غوښې څخه تر سهاره پورې هېڅ شی مه ساتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_25.mp3', '', 1761754199, 1761754199),
(46257, 'Exodus 34:26', 'Exodus', 34, 26, 'هر کال د خپل څښتن خدای کور ته د خپل لومړني حاصل ډېرې ښې غلې دانې راوړئ. یو سېرلی د خپلې مور په شیدو کې مه پخوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_26.mp3', '', 1761754199, 1761754199),
(46258, 'Exodus 34:27', 'Exodus', 34, 27, 'څښتن موسی ته وویل: «دا خبرې ولیکه، ځکه چې دا د هغه لوظ شرطونه دي چې ستا سره او د اسراییلو د قوم سره مې کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_27.mp3', '', 1761754199, 1761754199),
(46259, 'Exodus 34:28', 'Exodus', 34, 28, 'موسی څلوېښت شپې او څلوېښت ورځې د څښتن سره په غره کې پاتې شو، په دې ټوله موده کې هغه نه څه وڅښل او نه یې څه وخوړل. هغه د لوظ خبرې یعنې لس حکمونه په لوحو باندې ولیکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_28.mp3', '', 1761754199, 1761754199),
(46260, 'Exodus 34:29', 'Exodus', 34, 29, 'کله چې موسی د تیږو د دوو لوحو سره چې حکمونه ورباندې لیکل شوي وو د سینا له غره څخه راښکته شو، نو د هغه مخ ځلېده، ځکه چې هغه د څښتن سره خبرې کړې وې، خو هغه ورڅخه خبر نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_29.mp3', '', 1761754199, 1761754199),
(46261, 'Exodus 34:30', 'Exodus', 34, 30, 'کله چې هارون او د اسراییلو خلکو د موسی مخ ولیده چې ځلیږي، نو هغوی له وېرې موسی ته ورنژدې نه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_30.mp3', '', 1761754199, 1761754199),
(46262, 'Exodus 34:31', 'Exodus', 34, 31, 'خو موسی هغوی راوغوښتل. نو هارون او د قوم ټول مشران موسی ته ورغلل او موسی د هغوی سره خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_31.mp3', '', 1761754199, 1761754199),
(46263, 'Exodus 34:32', 'Exodus', 34, 32, 'وروسته ټول اسراییلیان موسی ته نژدې ورغلل او موسی هغوی ته هغه ټول حکمونه ورکړل چې څښتن هغه ته د سینا په غره باندې ورکړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_32.mp3', '', 1761754199, 1761754199),
(46264, 'Exodus 34:33', 'Exodus', 34, 33, 'کله چې موسی د هغوی سره خپلې خبرې خلاصې کړې، نو هغه خپل مخ په پردې باندې پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_33.mp3', '', 1761754199, 1761754199),
(46265, 'Exodus 34:34', 'Exodus', 34, 34, 'خو کله به چې موسی د څښتن د حضور خېمې ته ورننوت چې د څښتن سره خبرې وکړي، نو خپله پرده به یې لېرې کوله. چې کله به هغه راووت، نو خلکو ته به یې د څښتن حکمونه بیانول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_34.mp3', '', 1761754199, 1761754199),
(46266, 'Exodus 34:35', 'Exodus', 34, 35, 'او هغوی به لیدل چې د موسی مخ ځلیږي. تر هغه وخته پورې چې هغه به بیا څښتن ته د خبرو کولو دپاره تللو، نو په خپل مخ باندې به یې پرده اچوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus34_verse_35.mp3', '', 1761754199, 1761754199),
(46267, 'Hosea 14:1', 'Hosea', 14, 1, 'ای د اسراییلو خلکو، خپل څښتن خدای ته راوګرځئ، ځکه چې ستاسو ګناه ستاسو د رالوېدلو سبب شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_1.mp3', '', 1761754199, 1761754199),
(46268, 'Hosea 14:2', 'Hosea', 14, 2, 'څښتن ته راوګرځئ او د خپلو ګناهونو اقرار وکړئ او هغه ته ووایئ: «زمونږ ټول ګناهونه وبخښه او زمونږ دعا قبوله کړه، ترڅو مونږ ستا د ثنا او صفت سره تا ته قرباني وړاندې کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_2.mp3', '', 1761754199, 1761754199),
(46269, 'Hosea 14:3', 'Hosea', 14, 3, 'آشوریان مونږ هېڅکله ژغورلی نه شي او جنګي اسونه زمونږ ساتنه کولای نه شي. مونږ به نور هېڅکله په خپلو لاسونو جوړ شویو بتانو ته ونه وایو چې هغه زمونږ خدایان دي. ای څښتنه، یوازې ته یئ چې په یتیمانو باندې رحم کوې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_3.mp3', '', 1761754199, 1761754199),
(46270, 'Hosea 14:4', 'Hosea', 14, 4, 'څښتن وایي: زه به ختمه کړم د هغوی بې‌وفایي او شفا به ورکړم د زړه د اخلاصه به کړم مینه له هغوی سره او زه به هغوی باندې نور قهر نه کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_4.mp3', '', 1761754199, 1761754199),
(46271, 'Hosea 14:5', 'Hosea', 14, 5, 'زه به یم د اسراییلو دپاره لکه د پرخې په شان هغوی به وغوړیږي لکه ګلانو د سوسن په شان هغوی به ولري کلکې ریښې لکه د لبنان د سبر ونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_5.mp3', '', 1761754199, 1761754199),
(46272, 'Hosea 14:6', 'Hosea', 14, 6, 'د هغوی څانګې به خپرې شي او وي به ښایسته لکه زیتون د ونو په شان وي خوشبویي به د دوی د لبنان د سبر ونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_6.mp3', '', 1761754199, 1761754199),
(46273, 'Hosea 14:7', 'Hosea', 14, 7, 'هغوی به بیا تېروي ژوند زما د سیوري لاندې هغوی کري به غلې او وبه غوړیږي د انګور تاک په شان شي مشهور به هغوی لکه شراب د لبنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_7.mp3', '', 1761754199, 1761754199),
(46274, 'Hosea 14:8', 'Hosea', 14, 8, 'ای اسراییلو، تاسو به کار نه لرئ نور د بتانو سره هغه زه یم چې قبلوم به دعاګانې ستاسو او زه به کومه پام په تاسو باندې زه سرپناه به یم ستاسو دپاره د تل شنې ونې په شان ستاسو مېوه راځي زما له خوا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_8.mp3', '', 1761754199, 1761754199),
(46275, 'Hosea 14:9', 'Hosea', 14, 9, 'کوم خلک چې هوښیار دي، نو هغوی دې په دې خبرو باندې پوه شي او کوم خلک چې عقلمند دي، هغو ته دې په خپلو زړونو کې ځای ورکړي. د څښتن لارې سمې دي او صادقان خلک به په هغو باندې روان وي، خو سرکښه خلک به په دې لارو راولویږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea14_verse_9.mp3', '', 1761754199, 1761754199),
(46276, 'Genesis 6:3', 'Genesis', 6, 3, 'هغه وخت څښتن وویل: «زه به انسان پرېنږدم چې هغه د تل دپاره ژوندی وي او عمر به یې د یوسلو شلو کالو څخه زیات نه وي، ځکه چې هغه فاني دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_3.mp3', '', 1761754199, 1761754199),
(46277, 'Genesis 6:4', 'Genesis', 6, 4, 'کله چې فرښتو د انسانانو د لورګانو سره ودونه وکړل، د هغوی څخه ډېر لوی او قوي انسانان پیدا شول او د پخوانۍ زمانې او حتی وروسته هم مشهور جنګیالي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_4.mp3', '', 1761754199, 1761754199),
(46278, 'Genesis 6:5', 'Genesis', 6, 5, 'څښتن ولیدل چې په نړۍ کې د انسان بدکاري زیاته شوې ده او د دوی ټول خیالونه او ارادې تل بدې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_5.mp3', '', 1761754199, 1761754199),
(46279, 'Genesis 6:6', 'Genesis', 6, 6, 'نو څښتن پښېمانه شو او هغه خفه شو چې انسان یې د ځمکې په مخ پیدا کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_6.mp3', '', 1761754199, 1761754199),
(46280, 'Genesis 6:7', 'Genesis', 6, 7, 'نو هغه وویل: «زه به د ځمکې د مخ څخه ټول ژوندي مخلوقات له منځه یوسم! زه به انسانان، حیوانات، مرغان او خزندې له منځه یوسم. زه پښېمانه یم چې دوی مې پیدا کړل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_7.mp3', '', 1761754199, 1761754199),
(46281, 'Genesis 6:8', 'Genesis', 6, 8, 'خو څښتن د نوح څخه راضي ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_8.mp3', '', 1761754199, 1761754199),
(46282, 'Genesis 6:9', 'Genesis', 6, 9, 'دا د نوح کیسه ده. نوح په خپله زمانه کې نېک او پرهېزګار سړی ؤ او خدای ته ډېر نژدې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_9.mp3', '', 1761754199, 1761754199),
(46283, 'Genesis 6:10', 'Genesis', 6, 10, 'هغه درې زامن درلودل: سام، حام او یافت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_10.mp3', '', 1761754199, 1761754199),
(46284, 'Genesis 6:11', 'Genesis', 6, 11, 'خو د خدای په نظر کې ځمکه د فساد څخه ډکه شوې وه او د ظلم زیاتي لمن هرې خواته خپره شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_11.mp3', '', 1761754199, 1761754199),
(46285, 'Genesis 6:12', 'Genesis', 6, 12, 'خدای ولیدل چې دنیا فاسده شوې ده، ځکه چې ټول انسانان بې‌لارې شوي او فاسد شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_12.mp3', '', 1761754199, 1761754199),
(46286, 'Genesis 6:13', 'Genesis', 6, 13, 'خدای نوح ته وویل: «ما دا پرېکړه کړې ده چې ټول انساني نسل له منځه یوسم، ځکه چې دنیا د دوی د زور‌زیاتي د عملونو څخه ډکه شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_13.mp3', '', 1761754199, 1761754199),
(46287, 'Genesis 6:14', 'Genesis', 6, 14, 'د ځان دپاره د ډېرو ښو لرګیو څخه کشتۍ جوړه کړه، په هغې کې کوټې جوړې کړه او دننه او دباندې ورته د قیر پوښ ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_14.mp3', '', 1761754199, 1761754199),
(46288, 'Genesis 6:15', 'Genesis', 6, 15, 'هغه داسې جوړه کړه چې اوږدوالی یې یوسلو پنځه دېرش متره، سور یې دوه ویشت متره او لوړوالی یې دیارلس متره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_15.mp3', '', 1761754199, 1761754199),
(46289, 'Genesis 6:16', 'Genesis', 6, 16, 'په کشتۍ باندې یو بام جوړ کړه او د پنځه څلوېښت سانتي مترو په شاوخوا کې د بام او د کشتۍ د اړخ ترمنځ فاصله پرېږده. کشتۍ درې منزله جوړه کړه او په یوه اړخ کې ورته دروازه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_16.mp3', '', 1761754199, 1761754199),
(46290, 'Genesis 6:17', 'Genesis', 6, 17, 'زه په ځمکه باندې سېلاب راولم چې ټول ژوندي موجودات له منځه یوسي او هر هغه څه چې په ځمکه کې دي، مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_17.mp3', '', 1761754199, 1761754199),
(46291, 'Genesis 6:18', 'Genesis', 6, 18, 'خو زه به ستا سره لوظ وکړم چې ته به د خپلې ښځې، خپلو زامنو، او د خپلو زامنو د ښځو سره کشتۍ ته ورننوځې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_18.mp3', '', 1761754199, 1761754199),
(46292, 'Genesis 6:19', 'Genesis', 6, 19, 'د ټولو ژوندیو مخلوقاتو څخه یوه یوه جوړه نر او ښځه د ځان سره کشتۍ ته راوله، ترڅو هغه ژوندي وساتې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_19.mp3', '', 1761754199, 1761754199),
(46293, 'Genesis 6:20', 'Genesis', 6, 20, 'د هر ډول مرغانو، حیواناتو او خزندو څخه به دوه دوه تاته راشي، ترڅو هغه ژوندي وساتې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_20.mp3', '', 1761754199, 1761754199),
(46294, 'Genesis 6:21', 'Genesis', 6, 21, 'د خپل ځان او هغوی دپاره هر ډول خواړه د ځان سره واخله او ذخیره یې کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_21.mp3', '', 1761754199, 1761754199),
(46295, 'Genesis 6:22', 'Genesis', 6, 22, 'نو نوح ټول کارونه د خدای د حکم سره سم سرته ورسول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis6_verse_22.mp3', '', 1761754199, 1761754199),
(46296, 'Ezekiel 18:1', 'Ezekiel', 18, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_1.mp3', '', 1761754199, 1761754199),
(46297, 'Ezekiel 18:2', 'Ezekiel', 18, 2, '«د دې متل معنی څه ده چې خلک یې د اسراییلو په هېواد کې هر وخت وایي؟ تروه انګور وخوړل مور او پلار خو خوله تروه شوه د اولادونو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_2.mp3', '', 1761754199, 1761754199),
(46298, 'Ezekiel 18:3', 'Ezekiel', 18, 3, 'څښتن تعالی داسې وایي: «زه په خپل ذات باندې قسم خورم چې تاسو به دا متل په اسراییلو کې نور نه کاروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_3.mp3', '', 1761754199, 1761754199),
(46299, 'Ezekiel 18:4', 'Ezekiel', 18, 4, 'ځکه چې د هرچا ژوند زما په اختیار کې دی، که هغه د مور او پلار ژوند وي یا د هغوی د اولادونو ژوند وي. څوک چې ګناه وکړي، نو هغه به مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_4.mp3', '', 1761754199, 1761754199),
(46300, 'Ezekiel 18:5', 'Ezekiel', 18, 5, 'فرض کړئ چې یو سړی نېک او عادل دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_5.mp3', '', 1761754199, 1761754199),
(46301, 'Ezekiel 18:6', 'Ezekiel', 18, 6, 'او لکه څنګه چې نور اسراییلیان د بتانو عبادت کوي، هغه یې نه کوي او نه د غرونو په عبادت ځایونو کې د قربانۍ هغه غوښه چې بتانو ته وړاندې کیږي، خوري. هغه د بل چا ښځه نه بې‌پته کوي او نه د کومې ښځې سره د هغې د میاشتیني عادت په وخت کې یوځای کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_6.mp3', '', 1761754199, 1761754199),
(46302, 'Ezekiel 18:7', 'Ezekiel', 18, 7, 'هغه د چا سره ظلم نه کوي او نه د چا نه غلا کوي. هغه شی چې د ضمانت په توګه یې اخیستی وي، هغه بېرته ورکوي. وږیو خلکو ته خواړه ورکوي او لوڅو خلکو ته کالي ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_7.mp3', '', 1761754199, 1761754199),
(46303, 'Ezekiel 18:8', 'Ezekiel', 18, 8, 'هغه د سود اخیستلو په خاطر پیسې چاته په پور نه ورکوي. د بې‌انصافۍ نه ځان ساتي او د هرې شخړې په هکله عادلانه پرېکړه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_8.mp3', '', 1761754199, 1761754199),
(46304, 'Ezekiel 18:9', 'Ezekiel', 18, 9, 'دا ډول سړی زما د قوانینو نه پیروي کوي او په وفادارۍ سره زما په حکمونو باندې عمل کوي. هغه نېک سړی دی او هغه به خامخا ژوندی پاتې شي. څښتن تعالی داسې وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_9.mp3', '', 1761754199, 1761754199),
(46305, 'Ezekiel 18:10', 'Ezekiel', 18, 10, 'فرض کړئ چې دا سړی یو زوی لري چې ظلم او قتل کوي او داسې نور بد کارونه هم کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_10.mp3', '', 1761754199, 1761754199),
(46306, 'Ezekiel 18:11', 'Ezekiel', 18, 11, 'چې پلار یې هېڅکله نه دي کړي. هغه په غرونو کې د بتانو په عبادت ځایونو کې د قربانۍ غوښه خوري او د بل چا ښځه بې‌پته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_11.mp3', '', 1761754199, 1761754199),
(46307, 'Ezekiel 18:12', 'Ezekiel', 18, 12, 'هغه د غریبانو او محتاجو خلکو سره ظلم کوي، غلا کوي او هغه شی یې چې د امانت په توګه اخیستی وي، هغه بېرته نه ورکوي. هغه د بتانو عبادت او د کرکې وړ کارونه کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_12.mp3', '', 1761754199, 1761754199),
(46308, 'Ezekiel 18:13', 'Ezekiel', 18, 13, 'او په سود پیسې ورکوي. ایا هغه به ژوندی پاتې شي؟ نه، هغه به ژوندی پاتې نه شي. هغه دا ټول د کرکې وړ کارونه کړي دي، نو هغه به خامخا مړ شي. د هغه خون به د هغه په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_13.mp3', '', 1761754199, 1761754199),
(46309, 'Ezekiel 18:14', 'Ezekiel', 18, 14, 'اوس فرض کړئ دا دوهم سړی یو زوی ولري او هغه د خپل پلار ټول ګناهونه وویني، خو هغه د خپل پلار په شان کارونه نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_14.mp3', '', 1761754199, 1761754199),
(46310, 'Ezekiel 18:15', 'Ezekiel', 18, 15, 'لکه څنګه چې نور اسراییلیان د بتانو عبادت کوي، هغه یې نه کوي او نه د غرونو په عبادت ځایونو کې د قربانۍ هغه غوښه چې بتانو ته وړاندې کیږي، خوري. نه د بل چا ښځه بې‌پته کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_15.mp3', '', 1761754199, 1761754199);